// Merging the bundled catalog (`catalog.generated.json`) with the model.json.
import type { DomainDefault, DomainType, Model, ServiceDef, ServiceParam } from './types';
import { feelIfPossible } from './juelFeel.ts';
import { withOrchescalaTypes } from './orchescalaTypes.ts';
import type { CatalogFile } from './catalogImport';

// ── Bundled catalog ──────────────────────────────────────────────────────────
// `catalog.generated.json` is shipped with the app build (public/,
// generated by orchescala on every release from OpenAPI + site catalog).
// It is the delivered state of the projects: for the same identifier (id,
// topic, called process or type id) it wins over legacy entries of the
// model.json (an old import), which remain visible only where it has nothing.
//
// What is **built locally** wins over the delivery - one develops locally and
// overrides it on purpose: the projects in the list «Projekt-Ordner»
// (`model.projects`, «Neu aufbauen») with their types, and the services read
// with «OpenAPI einlesen» (`builtAt`). `localOverrides` says what is overridden,
// `withoutLocalProject` goes back to the delivery.
/** Defaults of a catalog entry in FEEL — older catalogs have `#{name}` */
const feelParams = (s: ServiceDef): ServiceDef => {
  const conv = (ps: ServiceParam[] | undefined) => ps?.map(p => (p.expression ? { ...p, expression: feelIfPossible(p.expression) } : p));
  return { ...s, ...(s.inputs ? { inputs: conv(s.inputs) } : {}), ...(s.outputs ? { outputs: conv(s.outputs) } : {}) };
};

/** Data of the domain scan that older catalogs don't have yet */
const NEWER_SCAN = ['routing', 'topicName', 'ownerDescr', 'ownerDescrExpr'] as const satisfies ReadonlyArray<keyof DomainType>;

// ── Domain types per project ─────────────────────────────────────────────────
// Merged by type ID, a project that moved types into another package
// (`…v1.CProcessState` → `…v1.schema.CProcessState`) would keep both versions:
// the old one from the catalog, the new one from the model.json. So the
// types of a project come from **one** side — the one scanned later.

/** The project folder from the path of the source (`acme-bpmn/01-domain/…`) */
const projectOfSource = (t: DomainType): string | null => {
  const at = t.source?.indexOf('/') ?? -1;
  return at > 0 ? t.source!.slice(0, at) : null;
};

/** The package root of the project: up to `.domain` or `.worker` (`acme.bpmn`) */
export const packageRoot = (pkg: string): string => {
  const parts = pkg.split('.');
  const at = parts.findIndex(p => p === 'domain' || p === 'worker');
  return (at > 0 ? parts.slice(0, at) : parts).join('.');
};

/**
 * The project of each type: from its source; without one (older catalogs,
 * OpenAPI, docs site) via the package root of the types that have one — the
 * model.json's scan always has a source, so every project scanned there gives
 * its root. If that is not unambiguous (a root shared by several projects, which
 * a scan already discards: «what is on top wins»), the type has no project and
 * is merged by ID as before — a moved package of it would keep both copies.
 */
function projectsOf(types: DomainType[]): (t: DomainType) => string | null {
  const byRoot = new Map<string, Set<string>>();
  for (const t of types) {
    const p = projectOfSource(t);
    if (!p || !t.pkg) continue;
    const root = packageRoot(t.pkg);
    byRoot.set(root, (byRoot.get(root) ?? new Set()).add(p));
  }
  return t => {
    const p = projectOfSource(t);
    if (p) return p;
    const found = t.pkg ? byRoot.get(packageRoot(t.pkg)) : undefined;
    return found?.size === 1 ? [...found][0] : null;
  };
}

const scanTime = (projects: Array<{ name: string; scannedAt?: string }> | undefined) => {
  const times = new Map<string, number>();
  for (const p of projects ?? []) {
    const ms = p.scannedAt ? Date.parse(p.scannedAt) : NaN;
    if (!Number.isNaN(ms)) times.set(p.name, ms);
  }
  return times;
};

/**
 * Per project: does the model.json's scan apply (otherwise the catalog's)?
 * Only a side with types of the project can win — a scan that found nothing
 * (or a project only listed) never wipes the other side's types. A project in
 * the local list (`model.projects`) with types wins: it is built locally on
 * purpose. Otherwise (types of an import) the later `scannedAt` wins; a scan without a time counts as older than one
 * with a time. Neither side has a time (scans from before `scannedAt`): the
 * model.json wins — it is scanned locally on demand, the catalog only with
 * the next release. The two times come from different clocks (browser, build
 * machine): fine for scans hours or days apart, not for minutes.
 */
export function projectWinners(user: Model, gen: CatalogFile, projectOf: (t: DomainType) => string | null): (project: string) => boolean {
  const userTime = scanTime(user.projects);
  const genTime = scanTime(gen.projects);
  const has = (types: DomainType[] | undefined) => new Set((types ?? []).map(projectOf).filter((p): p is string => !!p));
  const userHas = has(user.domainTypes);
  const genHas = has(gen.domainTypes);
  // a project in the local list is built locally on purpose - it wins, whatever the times
  const listed = new Set((user.projects ?? []).map(p => p.name));
  return project => {
    if (!userHas.has(project)) return false;
    if (!genHas.has(project) || listed.has(project)) return true;
    const u = userTime.get(project);
    const g = genTime.get(project);
    if (u != null && g != null) return u >= g;
    return g == null;
  };
}

// ── Built locally ────────────────────────────────────────────────────────────

/** The project of a service: the longest name of `names` its id, topic or called process starts with */
export function projectOfService(s: ServiceDef, names: Iterable<string>): string | null {
  const keys = [s.id, s.topic, s.calledProcess].filter((k): k is string => !!k);
  let best: string | null = null;
  for (const n of names) {
    if (!n || (best && best.length >= n.length)) continue;
    if (keys.some(k => k === n || k.startsWith(`${n}-`) || k.startsWith(`${n}.`))) best = n;
  }
  return best;
}

/**
 * The project of a locally built service (`builtAt`: by «Neu aufbauen» or «OpenAPI einlesen») -
 * null for any other entry (an old import, one written by hand): those stay behind the delivery
 * and «zurück zur Auslieferung» leaves them alone. The build sets the folder name as `group`;
 * one read with «OpenAPI einlesen» has a group from its process id - a listed project it starts
 * with is the better guess there.
 */
export function localProjectOf(s: ServiceDef, listed: ReadonlySet<string>): string | null {
  if (s.generated || !s.builtAt) return null;
  if (s.group && listed.has(s.group)) return s.group;
  return projectOfService(s, listed) || s.group || NO_PROJECT;
}

/** the project of a locally read service without `group` - one row in the overview, one way back */
export const NO_PROJECT = '(ohne Projekt)';

const time = (iso?: string): number => (iso ? Date.parse(iso) : NaN);
/** the later of two ISO times - an invalid one does not count */
const later = (a?: string, b?: string): string | undefined =>
  Number.isNaN(time(a)) ? (Number.isNaN(time(b)) ? undefined : b) : Number.isNaN(time(b)) || time(a) >= time(b) ? a : b;
/** is `a` before `b` - both valid times */
export const isBefore = (a?: string, b?: string): boolean => !Number.isNaN(time(a)) && !Number.isNaN(time(b)) && time(a) < time(b);
/** a time for the overview: the date - with the time of day when `other` is from the same day */
export const stampLabel = (iso?: string, other?: string): string => {
  if (Number.isNaN(time(iso))) return '?';
  const d = new Date(iso!);
  const sameDay = !Number.isNaN(time(other)) && new Date(other!).toDateString() === d.toDateString();
  return sameDay ? d.toLocaleString('de-CH', { dateStyle: 'short', timeStyle: 'short' }) : d.toLocaleDateString('de-CH');
};

/** the keys a service is known by - like with like: an id only meets an id, a topic a topic */
const keysOf = (s: ServiceDef) =>
  [['id', s.id], ['topic', s.topic], ['calls', s.calledProcess]].filter(([, v]) => !!v).map(([k, v]) => `${k}:${v}`);

/** the dependencies of the catalog's projects — those it read a `PROJECT.conf` of */
const dependenciesOf = (gen: CatalogFile): Record<string, string[]> | null => {
  const known = (gen.projects ?? []).filter(p => Array.isArray(p.dependencies));
  return known.length ? Object.fromEntries(known.map(p => [p.name, p.dependencies!])) : null;
};

export function mergeGeneratedCatalog(user0: Model, gen: CatalogFile | null): Model {
  // ProcessStatus & co. from orchescala.domain always exist — as «generated», so never in the model.json
  const user = { ...user0, services: user0.services.map(feelParams), domainTypes: withOrchescalaTypes(user0.domainTypes) };
  if (!gen) return user;
  const genServices = (gen.services ?? []).map(s => ({ ...feelParams(s), generated: true }));
  // what a newer scan than the catalog's tools recognises supplements the entry —
  // the catalog only gets it with the next release (switches of the decoder,
  // `final val topicName`, `override def descr`); what the catalog itself has applies
  const ownTypes = new Map((user.domainTypes ?? []).map(t => [t.id, t]));
  const projectOf = projectsOf([...(gen.domainTypes ?? []), ...(user.domainTypes ?? [])]);
  const userWins = projectWinners(user, gen, projectOf);
  const fromUser = (t: DomainType) => (p => p != null && userWins(p))(projectOf(t));
  const genTypes = (gen.domainTypes ?? []).filter(t => !fromUser(t)).map(t => {
    const own = ownTypes.get(t.id);
    const newer = Object.fromEntries(NEWER_SCAN.filter(k => own?.[k] != null && t[k] == null).map(k => [k, own![k]]));
    return { ...t, ...newer, generated: true };
  });
  // locally built services override delivered ones of the same id, topic or called process (each with its like)
  const listed = new Set((user.projects ?? []).map(p => p.name));
  const localServices = user.services.filter(s => localProjectOf(s, listed) != null);
  const localSet = new Set(localServices);
  const localKeys = new Set(localServices.flatMap(keysOf));
  const keptGen = genServices.filter(s => !keysOf(s).some(k => localKeys.has(k)));
  // a legacy entry steps back behind the delivery and behind a local build
  const kennt = new Set([...keptGen.flatMap(keysOf), ...localKeys]);
  const typIds = new Set(genTypes.map(t => t.id));
  // the example values (`default…`) follow the types: a project's come from the side whose scan
  // applies — a moved one would otherwise stay twice, and the catalog's (listed first) be chosen
  const defaultFromUser = (d: DomainDefault) => fromUser({ pkg: d.pkg } as DomainType);
  const projectOfDefault = (d: DomainDefault) => projectOf({ pkg: d.pkg } as DomainType);
  const genDefaults = (gen.domainDefaults ?? []).filter(d => !defaultFromUser(d)).map(d => ({ ...d, generated: true }));
  const defaultIds = new Set(genDefaults.map(d => `${d.pkg}.${d.name}`));
  const genDeps = dependenciesOf(gen);
  return {
    ...user,
    services: [
      ...keptGen,
      ...localServices,
      // legacy entries only where the delivery has nothing
      ...user.services.filter(s => !localSet.has(s) && !keysOf(s).some(k => kennt.has(k))),
    ],
    domainTypes: [...genTypes, ...(user.domainTypes ?? []).filter(t => {
      const p = projectOf(t);
      // the catalog's scan of the project applies: none of the older own types stays
      return p != null ? userWins(p) : !typIds.has(t.id);
    })],
    domainDefaults: [...genDefaults, ...(user.domainDefaults ?? []).filter(d =>
      (projectOfDefault(d) != null ? defaultFromUser(d) : !defaultIds.has(`${d.pkg}.${d.name}`)))],
    domainSources: gen.domainSources ?? user.domainSources,
    ...(gen.projectColors ? { projectColors: gen.projectColors } : {}),
    ...(genDeps ? { projectDependencies: genDeps } : {}),
  };
}

/** What a locally built project overrides of the delivery */
export interface CatalogOverride {
  project: string;
  /** delivered services replaced by local ones */
  services: number;
  /** delivered types of the project replaced by the local scan */
  types: number;
  /** when it was built locally (scan or OpenAPI) and when the delivery scanned it - ISO, if known */
  localAt?: string;
  deliveredAt?: string;
}

/** Per project: what the local build overrides of the delivered catalog (empty without one) */
export function localOverrides(user: Model, gen: CatalogFile | null): CatalogOverride[] {
  if (!gen) return [];
  const listed = new Set((user.projects ?? []).map(p => p.name));
  const out = new Map<string, CatalogOverride>();
  const entry = (project: string) => {
    let o = out.get(project);
    if (!o) { o = { project, services: 0, types: 0 }; out.set(project, o); }
    return o;
  };
  // services: a delivered one counts for the local project that replaces it
  const localByKey = new Map<string, { project: string; builtAt?: string }>();
  for (const s of user.services) {
    const p = localProjectOf(s, listed);
    if (p) for (const k of keysOf(s)) localByKey.set(k, { project: p, builtAt: s.builtAt });
  }
  for (const g of gen.services ?? []) {
    const hit = keysOf(g).map(k => localByKey.get(k)).find(Boolean);
    if (!hit) continue;
    const o = entry(hit.project);
    o.services++;
    o.localAt = later(o.localAt, hit.builtAt);
  }
  // types: the delivered types of a project whose local scan applies
  const projectOf = projectsOf([...(gen.domainTypes ?? []), ...(user.domainTypes ?? [])]);
  const userWins = projectWinners(user, gen, projectOf);
  for (const t of gen.domainTypes ?? []) {
    const p = projectOf(t);
    if (p && listed.has(p) && userWins(p)) entry(p).types++;
  }
  const scanned = new Map((user.projects ?? []).map(p => [p.name, p.scannedAt]));
  const delivered = new Map((gen.projects ?? []).map(p => [p.name, p.scannedAt]));
  return [...out.values()]
    .map(o => {
      const local = later(o.localAt, scanned.get(o.project));
      const at = delivered.get(o.project);
      return { ...o, ...(local ? { localAt: local } : {}), ...(at ? { deliveredAt: at } : {}) };
    })
    .sort((a, b) => a.project.localeCompare(b.project));
}

/**
 * Back to the delivery for a project: its locally built services and types (with their example
 * values) leave the model.json, and the project leaves the local list - a «Neu aufbauen» would
 * otherwise bring them back.
 */
export function withoutLocalProject(user: Model, project: string): Model {
  const listed = new Set((user.projects ?? []).map(p => p.name));
  const ofProject = (t: DomainType) => t.source?.startsWith(`${project}/`) ?? false;
  // the example values of the package roots only this project has - a root shared with another
  // project keeps its values
  const others = new Set((user.domainTypes ?? []).filter(t => !ofProject(t)).map(t => packageRoot(t.pkg ?? '')));
  const roots = new Set((user.domainTypes ?? []).filter(ofProject).map(t => packageRoot(t.pkg ?? '')).filter(r => r && !others.has(r)));
  return {
    ...user,
    services: user.services.filter(s => localProjectOf(s, listed) !== project),
    domainTypes: (user.domainTypes ?? []).filter(t => !ofProject(t)),
    domainDefaults: (user.domainDefaults ?? []).filter(d => !roots.has(packageRoot(d.pkg ?? ''))),
    projects: (user.projects ?? []).filter(p => p.name !== project),
  };
}

/**
 * The services of a fresh build: those of the projects' OpenAPI (`apis`, read by `rebuild`) come
 * in as built locally (`builtAt`) with the folder name as their project (`group`) - and replace
 * the ones an earlier build or read gave the same projects (`kept`: all others - merge the two
 * with `mergeServices`). `unreadable`: the projects whose OpenAPI could not be parsed - they keep
 * their services.
 */
export function rebuiltServices(
  existing: ServiceDef[],
  apis: Array<{ project: string; name: string; text: string }>,
  parse: (api: { name: string; text: string }) => { services: ServiceDef[]; types: DomainType[] },
  builtAt: string,
  /** `listed`: the projects of the local list - for a service read with «OpenAPI einlesen» whose
   * group is not the folder; `types`: the model's types - those an OpenAPI gave a project whose
   * OpenAPI did not come in now stay (`keptTypes`) */
  opts: { listed?: Iterable<string>; types?: DomainType[] } = {},
): { kept: ServiceDef[]; incoming: ServiceDef[]; types: DomainType[]; keptTypes: DomainType[]; unreadable: string[] } {
  const incoming: ServiceDef[] = [];
  const types: DomainType[] = [];
  const unreadable: string[] = [];
  for (const a of apis) {
    try {
      const c = parse(a);
      incoming.push(...c.services.map(sv => ({ ...sv, group: a.project, builtAt })));
      // the project's types are found by their source (`withoutLocalProject`, `localOverrides`)
      types.push(...c.types.map(t => (t.source ? t : { ...t, source: `${a.project}/03-api/${a.name}` })));
    } catch {
      unreadable.push(a.project);
    }
  }
  // only the projects whose OpenAPI came in replace their services: a project that could not be
  // read or parsed keeps what it had
  const projects = new Set(apis.map(a => a.project).filter(p => !unreadable.includes(p)));
  const listed = new Set(opts.listed ?? []);
  const kept = existing.filter(sv => !sv.generated && !projects.has(localProjectOf(sv, listed) ?? ''));
  const fromApi = (t: DomainType) => /^[^/]+\/03-api\//.test(t.source ?? '');
  const keptTypes = (opts.types ?? []).filter(t => !t.generated && fromApi(t) && !projects.has(t.source!.split('/')[0]));
  return { kept, incoming, types, keptTypes, unreadable };
}
